3d controles ƒ:
() => {
    // Gestos de cámara, solo sobre el FONDO (los chips y menús mandan en lo
    // suyo): arrastre primario = pan (agarra el plano: el punto bajo el
    // cursor se queda bajo el cursor), botón central o Alt+primario = órbita
    // alrededor de la mira, rueda = zoom hacia el punto bajo el cursor.
    // "3d reset !" (menú → actions #) devuelve la cámara al encuadre 1:1.
    if (diarsaba.get("3d controles ֎")) return;
    diarsaba.set("3d controles ֎", true);

    const THREE = window.THREE;
    const punto = (x, y) => diarsaba.get("3d punto en plano ƒ")(x, y);
    const pedir = () => diarsaba.get("3d render ƒ")();
    let modo = null;    // "pan" | "orbita"
    let ancla = null;   // punto del plano agarrado (pan)
    let ultimo = null;  // última posición de pantalla (órbita)

    window.addEventListener("pointerdown", (e) => {
        if (!diarsaba.get("es fondo ƒ")(e.target)) return;
        if (e.button === 1 || (e.button === 0 && e.altKey)) modo = "orbita";
        else if (e.button === 0) modo = "pan";
        else return;
        ancla = punto(e.clientX, e.clientY);
        ultimo = { x: e.clientX, y: e.clientY };
        e.preventDefault();
    }, true);

    window.addEventListener("pointermove", (e) => {
        if (!modo) return;
        const camara = diarsaba.get("3d camara ֎");
        const mira = diarsaba.get("3d mira ֎");
        if (!camara || !mira) return;

        if (modo === "pan" && ancla) {
            const ahora = punto(e.clientX, e.clientY);
            if (!ahora) return;
            // Trasladar cámara y mira juntas conserva la orientación.
            const delta = ancla.clone().sub(ahora);
            camara.position.add(delta);
            mira.add(delta);
            pedir();
        } else if (modo === "orbita" && ultimo) {
            const dx = e.clientX - ultimo.x;
            const dy = e.clientY - ultimo.y;
            ultimo = { x: e.clientX, y: e.clientY };
            const offset = camara.position.clone().sub(mira);
            const esf = new THREE.Spherical().setFromVector3(offset);
            esf.theta -= dx * 0.005;
            esf.phi -= dy * 0.005;
            // Sin pasar por los polos: en el polo exacto lookAt pierde el up
            // y la escena da un latigazo.
            esf.phi = Math.max(0.05, Math.min(Math.PI - 0.05, esf.phi));
            offset.setFromSpherical(esf);
            camara.position.copy(mira).add(offset);
            camara.lookAt(mira);
            pedir();
        }
    }, true);

    window.addEventListener("pointerup", () => {
        modo = null;
        ancla = null;
        ultimo = null;
    }, true);

    // passive: false — window registra wheel como pasivo por defecto y el
    // preventDefault no haría nada.
    window.addEventListener("wheel", (e) => {
        const camara = diarsaba.get("3d camara ֎");
        const mira = diarsaba.get("3d mira ֎");
        if (!camara || !mira) return;
        // La rueda sobre un menú o el editor es scroll, no zoom.
        if (e.target.closest && e.target.closest(".context-menu, .modal-content, .editor-overlay")) return;
        const factor = e.deltaY > 0 ? 1.1 : 1 / 1.1;
        // Zoom hacia el cursor: foco fijo, cámara y mira escalan hacia él.
        // El foco vive en z=0, igual que la mira, así que la mira no se sale
        // del plano y la órbita sigue girando alrededor de algo con chips.
        const foco = punto(e.clientX, e.clientY) || mira.clone();
        camara.position.sub(foco).multiplyScalar(factor).add(foco);
        mira.sub(foco).multiplyScalar(factor).add(foco);
        pedir();
        e.preventDefault();
    }, { passive: false, capture: true });
}

3d init ƒ:
() => {
    // Monta el lienzo 3d una sola vez. SIN CSS3DRenderer: un matrix3d con
    // perspectiva rasteriza el chip a una textura y la remuestrea — el
    // antialiasing del texto se pierde. Aquí three.js solo pone la cámara
    // y la matemática; los chips se PROYECTAN a left/top + font-size
    // ("3d proyectar ƒ") y el navegador rasteriza el texto a su tamaño
    // final, nítido. Lo vivo va bajo claves ֎, que guardar ya salta.
    if (diarsaba.get("3d escena ֎")) return;
    if (!window.THREE) {
        console.warn("[3d] window.THREE no está: los chips caen al body plano.");
        return;
    }
    const THREE = window.THREE;
    const escena = new THREE.Scene();
    const camara = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 1, 200000);
    const contenedor = document.createElement("div");
    contenedor.classList.add("escena-3d");
    document.body.appendChild(contenedor);

    diarsaba.set("3d escena ֎", escena);
    diarsaba.set("3d camara ֎", camara);
    diarsaba.set("3d contenedor ֎", contenedor);

    window.addEventListener("resize", () => {
        camara.aspect = window.innerWidth / window.innerHeight;
        camara.updateProjectionMatrix();
        diarsaba.get("3d render ƒ")();
    });

    diarsaba.get("3d reset ƒ")();
    diarsaba.get("3d controles ƒ")();
}

3d limpiar ƒ:
() => {
    // Vacía la escena de chips. Es el reemplazo de body.replaceChildren()
    // al cambiar de place: los chips ya no son hijos del body, y hay que
    // sacar cada uno del DOM Y del registro que recorre "3d proyectar ƒ".
    const escena = diarsaba.get("3d escena ֎");
    if (!escena) return;
    [...escena.children].forEach((obj) => {
        if (obj.element instanceof Element && obj.element.parentNode) {
            obj.element.parentNode.removeChild(obj.element);
        }
        escena.remove(obj);
    });
    diarsaba.get("3d render ƒ")();
}

3d proyectar ƒ:
() => {
    // BILLBOARD: cada chip se proyecta con la cámara y se escribe como
    // left/top (redondeados a píxel) + font-size según su profundidad.
    // Sin matrix3d el texto es layout de verdad —rasterizado nítido a su
    // tamaño final—; el precio es que el chip no se inclina: siempre mira
    // a la cámara, como una nube de etiquetas en 3d.
    const camara = diarsaba.get("3d camara ֎");
    const escena = diarsaba.get("3d escena ֎");
    if (!camara || !escena) return;
    camara.updateMatrixWorld();
    const w = window.innerWidth;
    const h = window.innerHeight;
    // A la distancia del encuadre 1:1 ("3d reset ƒ") la escala es 1 exacta.
    const d0 = (h / 2) / Math.tan((camara.fov * Math.PI) / 360);

    // Dos pasadas — primero TODAS las lecturas (offsetWidth fuerza layout),
    // luego todas las escrituras: un solo layout por frame, sin thrashing.
    const visibles = [];
    const ocultos = [];
    for (const obj of escena.children) {
        const el = obj.element;
        if (!(el instanceof Element)) continue;
        // Profundidad sobre el eje de la cámara (negativa por delante).
        const vista = obj.position.clone().applyMatrix4(camara.matrixWorldInverse);
        if (vista.z >= -1) { ocultos.push(el); continue; }
        const s = Math.min(Math.round((d0 / -vista.z) * 1000) / 1000, 50);
        const p = obj.position.clone().project(camara);
        visibles.push({
            el,
            x: ((p.x + 1) / 2) * w,
            y: ((1 - p.y) / 2) * h,
            s,
            prof: -vista.z,
            // Mitades para centrar el chip en su punto, como hacía CSS3D.
            // visibility (no display) al ocultar: conserva el layout y la
            // medida sigue valiendo cuando el chip reaparece.
            mw: el.offsetWidth / 2,
            mh: el.offsetHeight / 2,
        });
    }

    for (const el of ocultos) el.style.visibility = "hidden";
    // Los cercanos pintan encima: z-index por orden de profundidad.
    visibles.sort((a, b) => b.prof - a.prof);
    let z = 0;
    for (const c of visibles) {
        c.el.style.visibility = "";
        c.el.style.fontSize = c.s === 1 ? "" : `${c.s}rem`;
        c.el.style.left = `${Math.round(c.x - c.mw)}px`;
        c.el.style.top = `${Math.round(c.y - c.mh)}px`;
        c.el.style.zIndex = String(++z);
    }

    // Las aristas del modo grafo se redibujan con los chips ya proyectados
    // (leen su posición en pantalla). Si el modo está apagado, solo limpia.
    const grafo = diarsaba.get("grafo dibujar ƒ");
    if (grafo) grafo();
}

3d punto en plano ƒ:
(clientX, clientY) => {
    // Pantalla → mundo: el punto del plano z=0 (donde viven los chips) que
    // queda bajo ese píxel. Devuelve null si no hay cámara o si el rayo no
    // corta el plano (mirando al horizonte).
    const THREE = window.THREE;
    const camara = diarsaba.get("3d camara ֎");
    if (!THREE || !camara) return null;
    const ndc = new THREE.Vector2(
        (clientX / window.innerWidth) * 2 - 1,
        -(clientY / window.innerHeight) * 2 + 1
    );
    const ray = new THREE.Raycaster();
    ray.setFromCamera(ndc, camara);
    const plano = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
    return ray.ray.intersectPlane(plano, new THREE.Vector3());
}

3d render ƒ:
() => {
    // Render BAJO DEMANDA: se proyecta solo cuando algo cambió (cámara,
    // chips), coalesciendo las llamadas de un mismo frame en un rAF.
    // La pasada real vive en "3d proyectar ƒ".
    if (diarsaba.get("3d render pendiente ֎")) return;
    if (!diarsaba.get("3d camara ֎")) return;
    diarsaba.set("3d render pendiente ֎", true);
    requestAnimationFrame(() => {
        diarsaba.set("3d render pendiente ֎", false);
        diarsaba.get("3d proyectar ƒ")();
    });
}

3d reset ƒ:
() => {
    // Encuadre inicial 1:1: a esta distancia una unidad del plano z=0 mide un
    // píxel, así que las posiciones {x, y} guardadas en los places se ven
    // exactamente como en el diarsaba plano de antes. y va invertida porque
    // los places guardan y hacia abajo y three mide y hacia arriba.
    const THREE = window.THREE;
    const camara = diarsaba.get("3d camara ֎");
    if (!THREE || !camara) return;
    const cx = window.innerWidth / 2;
    const cy = window.innerHeight / 2;
    const d = cy / Math.tan((camara.fov * Math.PI) / 360);
    camara.position.set(cx, -cy, d);
    camara.up.set(0, 1, 0);
    camara.lookAt(cx, -cy, 0);
    const mira = diarsaba.get("3d mira ֎");
    if (mira) mira.set(cx, -cy, 0);
    else diarsaba.set("3d mira ֎", new THREE.Vector3(cx, -cy, 0));
    diarsaba.get("3d render ƒ")();
}

add to place ƒ:
(name) => {

    const current_place_name = diarsaba.get("current place §")

    if (current_place_name == null || current_place_name == undefined) {
        //si no existe un place ahora somos el place
        // unicamente si es un place

        if (name.slice(-1) == "@") {
            diarsaba.set("current place §", name)
        }else{
            host.notify("todos los movimientos que hagas no seran registrados")
        }

    } else {
        // 1. Declaramos la variable y evitamos que sea undefined
        let current_place = diarsaba.get(current_place_name) || {};

        // 2. Usamos un nombre de variable más seguro (asumiendo que 'name' viene de otro lado)
        const itemKey = name;

        // 3. Creamos un nuevo objeto (inmutabilidad) usando el spread operator (...)
        const updated_place = {
            ...current_place,
            [itemKey]: {
                x: diarsaba.get("open x $"),
                y: diarsaba.get("open y $")
            }
        };

        // 4. Guardamos el nuevo objeto
        diarsaba.set(current_place_name, updated_place);
        // Autosave: el place cambió (un chip nuevo con su posición).
        diarsaba.get("persistir atomo ƒ")(current_place_name);
    }
}

