buscar ƒ:
() => {
    // Paleta de búsqueda (Ctrl+K): filtra por nombre y, si no acierta, por el
    // TEXTO del átomo (código ƒ, §, <, {). Enter o clic teletransporta. El
    // overlay, el teclado y los resultados los dibuja el shell (host.palette);
    // aquí queda solo la LÓGICA: filtrar y a dónde ir. Ver CONTENEDOR.md.
    const filtrar = (q) => {
        q = q.trim().toLowerCase();
        if (!q) return [];
        const res = [];
        for (const k of diarsaba.keys()) {
            if (typeof k !== "string" || k.endsWith("֎")) continue;
            const nombre = k.toLowerCase();
            let score = -1;
            const idx = nombre.indexOf(q);
            // El nombre pesa más que el contenido, y cuanto antes aparezca.
            if (idx >= 0) score = 1000 - idx;
            else {
                const v = diarsaba.get(k);
                let texto = "";
                if (typeof v === "function") texto = String(v).toLowerCase();
                else if (typeof v === "string") texto = v.toLowerCase();
                if (texto && texto.includes(q)) score = 10;
            }
            if (score >= 0) res.push({ k, score });
        }
        res.sort((a, b) => b.score - a.score || a.k.localeCompare(b.k));
        return res.slice(0, 25).map((r) => r.k);
    };

    host.palette({ onQuery: filtrar, onPick: (k) => diarsaba.get("ir a ƒ")(k) });
}

clamp to viewport ƒ:
(el) => {
    // Reposiciona el elemento para que no se salga de la ventana (clamp).
    // Se mide el tamaño natural en (0,0): si se coloca desbordando, el ancho
    // shrink-to-fit del .context-menu se comprime y daría una medida errónea.
    const margin = 8;
    const vw = window.innerWidth;
    const vh = window.innerHeight;

    const desiredLeft = parseFloat(el.style.left) || 0;
    const desiredTop = parseFloat(el.style.top) || 0;

    el.style.left = "0px";
    el.style.top = "0px";
    const w = el.offsetWidth;
    const h = el.offsetHeight;

    let left = desiredLeft;
    let top = desiredTop;

    if (left + w > vw - margin) left = vw - margin - w;
    if (top + h > vh - margin) top = vh - margin - h;
    if (left < margin) left = margin;
    if (top < margin) top = margin;

    el.style.left = `${left}px`;
    el.style.top = `${top}px`;
}

clear menus ƒ:
() => {
    // Guard: los defaults serializados pueden ser {} (truthy sin .remove)
    const menu = diarsaba.get("current menu");
    if (menu && typeof menu.remove === "function") menu.remove();

    const chipMenu = diarsaba.get("current chip menu");
    if (chipMenu && typeof chipMenu.remove === "function") chipMenu.remove();

    // Los submenús se abren en cadena, así que no hay una sola
    // referencia que valga: se barren por su marca.
    document.querySelectorAll(".context-menu.submenu").forEach((el) => el.remove());

    // El panel de la bitácora no es un menú, pero un clic en el fondo también
    // debe cerrarlo.
    document.querySelectorAll(".bitacora-panel").forEach((el) => el.remove());
    document.querySelectorAll(".historial-panel").forEach((el) => el.remove());
}

create chip ƒ:
(x, y, text, parent = "", type = "") => {
    const div = document.createElement("div");
    div.classList = "object-name";
    div.textContent = text;
    div.spellcheck = false;
    div.dataset.parent = parent;
    div.dataset.type = type;

    const escena = diarsaba.get("3d escena ֎");
    const contenedor = diarsaba.get("3d contenedor ֎");
    if (!escena || !contenedor) {
        // Sin escena (three no cargó): al body plano, como siempre fue.
        div.style.left = `${x}px`;
        div.style.top = `${y}px`;
        document.body.appendChild(div);
        diarsaba.get("clamp to viewport ƒ")(div);
        return div;
    }

    // El chip vive en el plano z=0; y se invierte porque los places guardan
    // y hacia abajo (píxeles) y three mide y hacia arriba. Sin clamp: el
    // mundo ya no tiene bordes, la cámara va a donde estén los chips.
    const obj = new window.THREE.Object3D();
    obj.position.set(x, -y, 0);
    obj.element = div;
    escena.add(obj);
    div._obj3d = obj;
    contenedor.appendChild(div);

    // remove() del div debe sacar TAMBIÉN el objeto de la escena: quien
    // borra chips (· * ocultar, · * quitar, eliminar elemento del dom ƒ…)
    // solo conoce el div, y un objeto huérfano seguiría en el registro
    // que recorre "3d proyectar ƒ".
    const removeDom = div.remove.bind(div);
    div.remove = () => {
        escena.remove(obj);
        removeDom();
        diarsaba.get("3d render ƒ")();
    };

    diarsaba.get("3d render ƒ")();
    return div;
}

