grafo activar ƒ:
() => {
    // Calcula las aristas del place ACTUAL: entre chips hermanos, una flecha
    // A→B si A referencia a B. Se computa aquí (una vez, al activar o cambiar
    // de place) y se cachea en "grafo aristas ֎"; el dibujo por frame solo
    // reproyecta, porque la topología no cambia al panear la cámara.
    const placeName = diarsaba.get("current place §");
    const place = diarsaba.get(placeName);
    const aristas = [];
    if (place && typeof place === "object" && !Array.isArray(place)) {
        const enPlace = Object.keys(place);
        const set = new Set(enPlace);
        const referencias = diarsaba.get("referencias de ƒ");
        for (const b of enPlace) {
            // referencias de ƒ(b) = quién nombra a b; nos quedamos con los que
            // también están en este place (los dos extremos deben verse).
            for (const a of referencias(b)) {
                if (a !== b && set.has(a)) aristas.push([a, b]);
            }
        }
    }
    diarsaba.set("grafo aristas ֎", aristas);
    return aristas.length;
}

grafo dibujar ƒ:
() => {
    // Pasada de dibujo, llamada al final de "3d proyectar ƒ" (cada frame). Lee
    // la posición en pantalla de cada extremo (los chips ya están proyectados)
    // y traza la arista con una flecha en el destino. Si el modo está apagado,
    // solo limpia. Monocromo: líneas y flechas en blanco translúcido.
    const canvas = diarsaba.get("grafo lienzo ֎");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (canvas.width !== window.innerWidth || canvas.height !== window.innerHeight) {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
    }
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (!diarsaba.get("grafo activo §")) return;

    const aristas = diarsaba.get("grafo aristas ֎") || [];
    const cache = {};
    const centro = (nombre) => {
        if (nombre in cache) return cache[nombre];
        let c = null;
        const chip = diarsaba.get(`${nombre} ֎`);
        if (chip instanceof Element && chip.style.visibility !== "hidden") {
            const r = chip.getBoundingClientRect();
            if (r.width) c = { x: r.left + r.width / 2, y: r.top + r.height / 2 };
        }
        cache[nombre] = c;
        return c;
    };

    ctx.lineWidth = 1;
    ctx.strokeStyle = "rgba(255, 255, 255, 0.22)";
    ctx.fillStyle = "rgba(255, 255, 255, 0.4)";
    for (const [a, b] of aristas) {
        const ca = centro(a), cb = centro(b);
        if (!ca || !cb) continue;
        ctx.beginPath();
        ctx.moveTo(ca.x, ca.y);
        ctx.lineTo(cb.x, cb.y);
        ctx.stroke();
        // Flecha en el destino, retirada un poco del centro para no clavarse
        // bajo el chip.
        const ang = Math.atan2(cb.y - ca.y, cb.x - ca.x);
        const px = cb.x - Math.cos(ang) * 16;
        const py = cb.y - Math.sin(ang) * 16;
        ctx.beginPath();
        ctx.moveTo(px, py);
        ctx.lineTo(px - Math.cos(ang - 0.4) * 8, py - Math.sin(ang - 0.4) * 8);
        ctx.lineTo(px - Math.cos(ang + 0.4) * 8, py - Math.sin(ang + 0.4) * 8);
        ctx.closePath();
        ctx.fill();
    }
}

