handle click ƒ:
async () => {
    // Con el modo mover activo, un clic en un CHIP lo arrastra y no lo abre.
    if (diarsaba.get("moviendo chips §")) {
        const ev = diarsaba.get("pointer up event");
        if (ev && ev.target && ev.target.closest && ev.target.closest(".object-name")) return;
    }

    // En panorámica un clic sobre un chip vuela a su place; en el vacío sale;
    // un ARRASTRE (pan de la cámara) no hace ninguna de las dos.
    if (diarsaba.get("panorámica activa §")) {
        const up = diarsaba.get("pointer up event");
        const down = diarsaba.get("pointer down event");
        const arrastro = down && up
            && Math.hypot(up.clientX - down.clientX, up.clientY - down.clientY) > 6;
        const chip = up.target && up.target.closest && up.target.closest(".object-name");
        if (chip && chip.dataset.pano) diarsaba.get("panorámica entrar ƒ")(chip.dataset.pano);
        else if (!arrastro) diarsaba.get("panorámica ƒ")();
        return;
    }

    const event = diarsaba.get("pointer up event");
    const target = event.target;

    // Los modales (editor Monaco, modal de nombre) viven ENCIMA del lienzo pero
    // este manejador escucha toda la ventana: no deben leerse como chips.
    if (event.target.closest && event.target.closest(".editor-overlay, .modal-content")) return;

    // Los MENÚS y LISTAS se despachan SOLOS (host.menu/host.list → despachar
    // menú ƒ, con stopPropagation). Aquí ya no se leen: un clic dentro de uno
    // no sigue. Antes este manejador contenía todo el despacho de menús.
    if (target.closest && target.closest(".context-menu")) return;

    // Fondo (body o escena 3d vacía) → solo limpiar menús.
    if (diarsaba.get("es fondo ƒ")(target)) {
        diarsaba.get("clear menus ƒ")();
        return;
    }

    // Chip del lienzo: el doble clic abre su editor (o cambia de place si es @).
    const content = target.textContent;
    let last_click = diarsaba.get("last click on §");
    if (last_click == undefined || last_click == null) {
        diarsaba.set("last click on §", content);
    } else {
        if (last_click == content) {
            if (content.slice(-1) == "@") {
                diarsaba.get("on double tap place ƒ")();
            } else {
                const editables = diarsaba.get("editables list #");
                if (editables.includes(content.slice(-1))) {
                    diarsaba.get("open general editor ƒ")(content);
                }
            }
            diarsaba.set("last click on §", null);
        } else {
            diarsaba.set("last click on §", content);
        }
    }

    diarsaba.get("clear menus ƒ")();
}

install mover ƒ:
() => {
    // Arrastre de chips. Es un MODO —lo enciende "mover !" en el menú
    // principal— porque mientras está activo el clic no abre ni edita.
    //
    // Los listeners van en window y solo deben registrarse una vez; la marca
    // ֎ no se persiste, así que cada arranque los pone de nuevo.
    if (diarsaba.get("mover instalado ֎")) return;
    diarsaba.set("mover instalado ֎", true);

    let arrastrando = null;
    let desfase = null; // chip 3d: posición del objeto - punto agarrado
    let dx = 0;         // fallback body plano
    let dy = 0;

    // Capture: hay que llegar ANTES que los listeners de on start ƒ para poder
    // cortar el clic que abriría el chip.
    window.addEventListener(
        "pointerdown",
        (e) => {
            if (!diarsaba.get("moviendo chips §")) return;
            // Solo el botón primario: el derecho abre el menú, y es por donde
            // se sale del modo.
            if (e.button !== 0) return;
            const chip = e.target.closest(".object-name");
            if (!chip) return;
            arrastrando = chip;
            const obj = chip._obj3d;
            const p = obj ? diarsaba.get("3d punto en plano ƒ")(e.clientX, e.clientY) : null;
            if (obj && p) {
                // El chip se agarra por donde se toca: el desfase evita el
                // salto al centro.
                desfase = obj.position.clone().sub(p);
            } else {
                desfase = null;
                const r = chip.getBoundingClientRect();
                dx = e.clientX - r.left;
                dy = e.clientY - r.top;
            }
            chip.setPointerCapture?.(e.pointerId);
            chip.classList.add("arrastrando");
            e.stopPropagation();
            e.preventDefault();
        },
        true
    );

    window.addEventListener(
        "pointermove",
        (e) => {
            if (!arrastrando) return;
            const obj = arrastrando._obj3d;
            if (obj && desfase) {
                const p = diarsaba.get("3d punto en plano ƒ")(e.clientX, e.clientY);
                if (p) {
                    obj.position.copy(p.add(desfase));
                    diarsaba.get("3d render ƒ")();
                }
            } else {
                arrastrando.style.left = `${e.clientX - dx}px`;
                arrastrando.style.top = `${e.clientY - dy}px`;
            }
            e.stopPropagation();
        },
        true
    );

    window.addEventListener(
        "pointerup",
        (e) => {
            if (!arrastrando) return;
            const chip = arrastrando;
            arrastrando = null;
            desfase = null;
            chip.classList.remove("arrastrando");

            // La posición se guarda en el place actual, que es donde vive la
            // disposición. Si el átomo no está en el place (p. ej. un chip
            // hijo abierto), se mueve pero no se registra: no tiene sitio ahí.
            const nombre = chip.textContent;
            const placeName = diarsaba.get("current place §");
            const place = diarsaba.get(placeName);
            if (place && typeof place === "object" && nombre in place) {
                const obj = chip._obj3d;
                const pos = obj
                    ? { x: obj.position.x, y: -obj.position.y }
                    : { x: parseFloat(chip.style.left) || 0, y: parseFloat(chip.style.top) || 0 };
                diarsaba.set(placeName, { ...place, [nombre]: pos });
                // Autosave: la nueva posición vive en el place.
                diarsaba.get("persistir atomo ƒ")(placeName);
            }

            // Cortamos el clic: si no, al soltar se abriría el chip.
            e.stopPropagation();
            e.preventDefault();
        },
        true
    );
}

install style manager ƒ:
() => {
    const styleIdFromKey = (k) => {
        const base = String(k).replace(/\s*\{$/, "").trim();
        return 'diarsaba-style-' + base.replace(/[^\w-]/g, '_').replace(/^_+|_+$/g, '');
    };

    // crear inicialmente las etiquetas <style> para claves que terminen en '{'
    for (const [k, v] of diarsaba.entries()) {
        if (typeof k === 'string' && k.endsWith('{')) {
            const id = styleIdFromKey(k);
            if (!document.getElementById(id)) {
                const el = document.createElement('style');
                el.id = id;
                el.textContent = typeof v === 'string' ? v : '';
                document.head.appendChild(el);
            }
        }
    }

    // override diarsaba.set para mantener sincronizados los estilos
    const originalSet = diarsaba.set.bind(diarsaba);
    diarsaba.set = (key, value) => {
        originalSet(key, value);
        try {
            if (typeof key === 'string' && key.endsWith('{')) {
                const id = styleIdFromKey(key);
                let el = document.getElementById(id);
                if (el) el.textContent = typeof value === 'string' ? value : '';
                else {
                    el = document.createElement('style');
                    el.id = id;
                    el.textContent = typeof value === 'string' ? value : '';
                    document.head.appendChild(el);
                }
            }
        } catch (e) { console.error('install style manager error', e); }
        return diarsaba;
    };
}

ir a ƒ:
(nombre) => {
    // Teletransporte: si es un place, entra; si no, entra a un place que lo
    // contenga (el primero) y resalta su chip; si no vive en ninguno, al
    // menos abre su editor. La verdad de "dónde está" la da padres de ƒ.
    if (typeof nombre !== "string") return;

    if (nombre.endsWith("@")) {
        diarsaba.set("pointer up event", { target: { textContent: nombre, nodeName: "SPAN" } });
        diarsaba.get("on double tap place ƒ")();
        return;
    }

    const padres = diarsaba.get("padres de ƒ")(nombre);
    if (padres.length) {
        diarsaba.set("pointer up event", { target: { textContent: padres[0], nodeName: "SPAN" } });
        diarsaba.get("on double tap place ƒ")();
        diarsaba.get("resaltar chip ƒ")(nombre);
        return;
    }

    // Sin place: no hay dónde llevarte, pero abrir su editor sigue siendo útil.
    const editables = diarsaba.get("editables list #");
    if (Array.isArray(editables) && editables.includes(nombre.slice(-1))) {
        diarsaba.get("open general editor ƒ")(nombre);
