    });
    window.addEventListener("pointerdown", (e) => {
        diarsaba.set("pointer down event", e);
        threads(`pointer down ${e.button} ~`);
    });
    window.addEventListener("pointermove", (e) => {
        diarsaba.set("pointer move event", e);
        diarsaba.set("pointer x", e.clientX);
        diarsaba.set("pointer y", e.clientY);
        //threads(`pointer move ~`)
    });

    window.addEventListener("keydown", (e) => {
        // Ctrl/Cmd+K abre el buscador. El input del buscador detiene la
        // propagación, así que teclear dentro no lo reabre.
        if (e.key === "Escape" && diarsaba.get("panorámica activa §")) {
            diarsaba.get("panorámica ƒ")();
            return;
        }
        if ((e.ctrlKey || e.metaKey) && (e.key === "k" || e.key === "K")) {
            e.preventDefault();
            const abrir = diarsaba.get("buscar ƒ");
            if (abrir) abrir();
            return;
        }
    });

    diarsaba.get("on start place ƒ")()

    diarsaba.get("install mover ƒ")();

    // Escuchar streams entrantes desde el arranque: si el handler se
    // registrara más tarde, un stream podría llegar antes que él.
    const p2pEscuchar = diarsaba.get("p2p ƒ @ StreamHandle ƒ");
    if (p2pEscuchar) Promise.resolve()
        .then(() => p2pEscuchar())
        .catch((e) => console.error('[p2p ƒ] no se pudo escuchar al arrancar', e));


}

open general editor ƒ:
async (key) => {
    // Delegamos en el editor específico del tipo, que serializa y reconstruye
    // cada tipo según el sufijo de la clave. Así el átomo vuelve SIEMPRE a su
    // tipo original: un # sigue siendo lista y un @ sigue siendo place.
    const type = key.slice(-1);
    const specificEditor = diarsaba.get(`· ${type} editor ƒ`);

    if (specificEditor) {
        await specificEditor({ parent: key });
        return;
    }

    // Sin editor específico. Un valor estructurado se edita como JSON:
    // String(objeto) daría "[object Object]" y guardarlo lo destruiría.
    const actual = diarsaba.get(key);
    const esEstructura = actual !== null && typeof actual === "object";
    const res = await host.editor(
        key,
        esEstructura ? JSON.stringify(actual, null, 2) : String(actual ?? ""),
        esEstructura ? "json" : "text"
    );
    if (res == null) return;

    if (esEstructura) {
        try {
            diarsaba.set(key, JSON.parse(res));
            await diarsaba.get("persistir atomo ƒ")(key);
        } catch (e) {
            host.notify(`"${key}" no se guardó: el JSON no es válido.\n\n${e.message}`);
        }
        return;
    }
    diarsaba.set(key, res);
    await diarsaba.get("persistir atomo ƒ")(key);
}

open submenu ƒ:
(nombre, rect) => {
    // Dibuja el contenido de una lista "#" como submenú, con la misma función
    // que el menú principal — un submenú ES un menú: sus ítems se pulsan igual
    // (create list menu ƒ cablea el despacho) y una lista dentro de otra vuelve
    // a abrirse aquí, anidando sola. Recibe "rect" (dato del shell) en vez del
    // elemento DOM. Devuelve false si el átomo no es una lista.
    const lista = diarsaba.get(nombre);
    if (!Array.isArray(lista)) return false;

    // Pulsar dos veces el mismo ítem no debe apilar submenús.
    const previo = diarsaba.get(`${nombre} submenu ֎`);
    if (previo && typeof previo.remove === "function") previo.remove();

    const sub = diarsaba.get("create list menu ƒ")(lista, nombre, "", rect.right + 6, rect.top);
    // La marca permite a "clear menus ƒ" barrerlos todos sin llevar la cuenta.
    sub.classList.add("submenu");
    diarsaba.set(`${nombre} submenu ֎`, sub);
    return true;
}

