        const p = arg(peer) || diarsaba.get("p2p ƒ @ peer §");
        if (!p) return dice("enviar ✗", "sin peer: corre FindProviders antes, o pásale uno");
        const carga = valor === undefined ? diarsaba.get("p2p ƒ @ enviar :") : arg(valor);
        const s = await diarsaba.get("p2p ƒ @ abrir o reusar ƒ")(p);
        await s.escribir(carga === undefined ? null : carga);
