p2p ƒ @ recibir ƒ:
(peer, msg) => {
    // Corre por CADA mensaje entrante, en cuanto llega. Dos cosas:
    //   1. Traza para el ojo: el log rodante info/data (últimos "historial $").
    //      "Streams data #"[0] es siempre el último dato, crudo y fácil de tomar.
    //   2. Despacho: si el mensaje trae una "orden", se ejecuta el átomo que la
    //      maneja ("al recibir <orden> ƒ") — así se ACTÚA al llegar, sin
    //      depender de alcanzar a leer el log antes de que se recorte.
    const hora = new Date().toLocaleTimeString();
    const tope = Number(diarsaba.get("p2p ƒ @ historial $")) || 50;
    diarsaba.set("Streams info #", [`${hora} ← ${peer.slice(-8)}`, ...(diarsaba.get("Streams info #") || [])].slice(0, tope));
    diarsaba.set("Streams data #", [msg, ...(diarsaba.get("Streams data #") || [])].slice(0, tope));

    if (msg && typeof msg === "object" && msg.orden) {
        const handler = diarsaba.get(`al recibir ${msg.orden} ƒ`);
        if (handler) {
            try { handler(msg, peer); }
            catch (e) { console.error("[p2p ƒ] al recibir", msg.orden, e); }
        }
    }
    console.log("[p2p ƒ] ←", peer.slice(-8), msg);
}

p2p ƒ @ stream ƒ:
(id, peer) => {
    // Un Stream vive en Go; aquí llega su identificador. Esto lo envuelve para
    // un stream PERSISTENTE con framing por "\n": se abre una vez por peer y por
    // él van muchos mensajes, cada uno terminado en salto de línea.
    //
    // El base64 de abajo NO es el formato: es el salto Go↔JS, que es JSON por
    // definición de los bindings de Wails y codifica []byte en base64.
    const aB64 = (t) => { const b = new TextEncoder().encode(t); let s = ""; for (const x of b) s += String.fromCharCode(x); return btoa(s); };
    const deB64 = (b) => new TextDecoder().decode(Uint8Array.from(atob(b), (c) => c.charCodeAt(0)));

    return {
        id,
        peer: peer || "",

        // Cada mensaje termina en "\n". JSON.stringify nunca emite un salto de
        // línea crudo (los escapa como \n, dos caracteres), así que el
        // delimitador jamás choca con el contenido. Un string se manda tal cual
        // (+ \n) para poder hablar con un peer que espera texto plano.
        escribir: async (valor) => {
            const texto = typeof valor === "string" ? valor : JSON.stringify(valor);
            return await host.p2p.StreamWrite(id, aB64(texto + "\n"));
        },

        // Bucle continuo: acumula bytes, corta por "\n" y despacha cada línea.
        // Lo que quede a medias se guarda en buf para la próxima lectura. Corre
        // hasta que el peer cierra (EOF) o se cae la conexión.
        escuchar: async (onMensaje) => {
            let buf = "";
            try {
                for (;;) {
                    const c = await host.p2p.StreamRead(id, 0, 0);
                    if (c.data) {
                        buf += deB64(c.data);
                        let i;
                        while ((i = buf.indexOf("\n")) >= 0) {
                            const linea = buf.slice(0, i);
                            buf = buf.slice(i + 1);
                            if (linea === "") continue;
                            let msg;
                            try { msg = JSON.parse(linea); } catch (_) { msg = linea; }
                            onMensaje(msg);
                        }
                    }
                    if (c.eof) break;
                }
            } catch (e) {
                console.error("[p2p ƒ] lector de", (peer || "").slice(-8), "cayó:", e.message || e);
            } finally {
                // Al caerse, saca este peer del registro para que un envío
                // futuro reabra en vez de escribir en un stream muerto.
                const conns = diarsaba.get("p2p ƒ @ conns ֎");
                if (conns && conns.get(peer) && conns.get(peer).id === id) conns.delete(peer);
            }
        },

        cerrar: async () => await host.p2p.StreamClose(id),
    };
}

padres de ƒ:
(nombre) => {
    // ¿Quién tiene a este átomo como hijo? Los places YA lo saben — cada uno
    // lista sus hijos con posición—; esto solo lo lee al revés. Se CALCULA
    // cada vez y no se guarda en ningún lado: un índice almacenado habría
    // que mantenerlo en cada tomar/quitar/eliminar y mentiría en cuanto un
    // camino lo olvidara. El mapa vive en memoria; recorrerlo es gratis.
    const padres = [];
    for (const [k, v] of diarsaba.entries()) {
        if (typeof k === "string" && k.endsWith("@") && v && typeof v === "object") {
            if (Object.prototype.hasOwnProperty.call(v, nombre)) padres.push(k);
        }
    }
    return padres;
}

panorámica entrar ƒ:
(placeName) => {
    // Vuela la cámara hacia el cluster del place y luego entra (el núcleo lo
    // repinta con su encuadre 1:1). El vuelo es un tween acotado (~380ms): es
    // interacción del usuario y termina solo, así que no rompe el render bajo
    // demanda.
    const THREE = window.THREE;
    const camara = diarsaba.get("3d camara ֎");
    const centros = diarsaba.get("panorámica centros ֎") || {};
    const destino = centros[placeName];

    const entrar = () => {
        diarsaba.set("panorámica activa §", "");
        document.body.classList.remove("modo-panoramica");
        diarsaba.get("3d limpiar ƒ")();
        diarsaba.set("pointer up event", { target: { textContent: placeName, nodeName: "SPAN" } });
        diarsaba.get("on double tap place ƒ")();
    };

    if (!THREE || !camara || !destino) { entrar(); return; }

    const desde = camara.position.clone();
    const miraDesde = (diarsaba.get("3d mira ֎") || new THREE.Vector3()).clone();
    const posObj = new THREE.Vector3(destino.x, -destino.y, 640);
    const miraObj = new THREE.Vector3(destino.x, -destino.y, 0);
    const t0 = performance.now();
    const dur = 380;

    const paso = () => {
        const t = Math.min((performance.now() - t0) / dur, 1);
        const e = t * t * (3 - 2 * t); // smoothstep
        camara.position.lerpVectors(desde, posObj, e);
        const m = miraDesde.clone().lerp(miraObj, e);
        camara.lookAt(m);
        diarsaba.set("3d mira ֎", m);
        diarsaba.get("3d proyectar ƒ")();
        if (t < 1) requestAnimationFrame(paso);
        else entrar();
    };
    requestAnimationFrame(paso);
}

panorámica pintar ƒ:
() => {
    // Pinta cada place como un cluster: su etiqueta arriba y sus chips debajo,
    // a escala, conservando su disposición relativa. Todo en "pano-pixel"
    // (y hacia abajo, como los places), que create chip ƒ ya entiende. Marca
    // cada chip con dataset.pano = nombre del place para que un clic sepa a
    // dónde volar. Luego encuadra la cámara para verlos todos.
    const places = diarsaba.get("places #") || [];
    const escala = 0.4;
    const cols = Math.max(1, Math.ceil(Math.sqrt(places.length)));
    const sepX = 1100, sepY = 820;
    const centros = {};
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    const abarca = (x, y) => {
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
    };

    places.forEach((placeName, i) => {
        const cx = (i % cols) * sepX;
        const cy = Math.floor(i / cols) * sepY;
        centros[placeName] = { x: cx, y: cy };

        const place = diarsaba.get(placeName);
        const hijos = (place && typeof place === "object" && !Array.isArray(place))
            ? Object.entries(place) : [];

        // Centroide del place para centrar el cluster en (cx, cy).
        let sx = 0, sy = 0, n = 0;
        for (const [, p] of hijos) { sx += p.x; sy += p.y; n++; }
        const ccx = n ? sx / n : 0, ccy = n ? sy / n : 0;

        // Etiqueta del place (arriba del cluster).
        const label = diarsaba.get("create chip ƒ")(cx, cy - 190, placeName, "", "@");
        if (label) { label.dataset.pano = placeName; label.classList.add("pano-label"); }
        abarca(cx, cy - 190);

        for (const [nombre, p] of hijos) {
            const px = cx + (p.x - ccx) * escala;
            const py = cy + (p.y - ccy) * escala;
            const c = diarsaba.get("create chip ƒ")(px, py, nombre, "", nombre.slice(-1));
            if (c) c.dataset.pano = placeName;
            abarca(px, py);
        }
    });

    diarsaba.set("panorámica centros ֎", centros);

    // Encuadrar la cámara para que todas las constelaciones quepan.
    const THREE = window.THREE;
    const camara = diarsaba.get("3d camara ֎");
    if (THREE && camara && isFinite(minX)) {
        const bcx = (minX + maxX) / 2, bcy = (minY + maxY) / 2;
        const bw = (maxX - minX) + 500, bh = (maxY - minY) + 500;
        const fov = (camara.fov * Math.PI) / 180;
        const distH = (bh / 2) / Math.tan(fov / 2);
        const distW = (bw / 2) / (Math.tan(fov / 2) * camara.aspect);
        const dist = Math.max(distH, distW) * 1.08;
        const mira = new THREE.Vector3(bcx, -bcy, 0);
        camara.position.set(bcx, -bcy, dist);
        camara.up.set(0, 1, 0);
        camara.lookAt(mira);
        diarsaba.set("3d mira ֎", mira);
    }
    diarsaba.get("3d render ƒ")();
}

panorámica ƒ:
() => {
    // Enciende/apaga la PANORÁMICA: una vista que aleja la cámara y muestra
    // TODOS los places como constelaciones de chips. Es aditiva —el núcleo
    // (current place §, on double tap place ƒ, pintado z=0) no se toca—: la
    // panorámica pinta sus PROPIOS chips desechables (sin registrar refs
    // "${name} ֎", para que un átomo presente en varios places no choque) y al
    // entrar a un place los limpia y devuelve el control al núcleo.
    const activa = !diarsaba.get("panorámica activa §");

    // Limpiar la escena y las refs de chips (la infraestructura del lienzo
    // sobrevive por su clase, igual que en on double tap place ƒ).
    for (const k of [...diarsaba.keys()]) {
        if (typeof k !== "string" || !k.endsWith("֎")) continue;
        const el = diarsaba.get(k);
        if (el instanceof Element
            && !el.classList.contains("escena-3d")
            && !el.classList.contains("grafo-lienzo")) {
            diarsaba.delete(k);
        }
    }
    diarsaba.get("3d limpiar ƒ")();

    if (activa) {
        diarsaba.set("panorámica activa §", "si");
        document.body.classList.add("modo-panoramica");
        diarsaba.get("panorámica pintar ƒ")();
    } else {
        diarsaba.set("panorámica activa §", "");
        document.body.classList.remove("modo-panoramica");
        // Volver al place actual (lo repinta el núcleo, con su encuadre 1:1).
        const actual = diarsaba.get("current place §");
        diarsaba.set("pointer up event", { target: { textContent: actual, nodeName: "SPAN" } });
        diarsaba.get("on double tap place ƒ")();
    }
    return activa ? "panorámica" : "cerrada";
}

persistir atomo ƒ:
async (name) => {
    // Autosave granular: persiste UN átomo en la base (bbolt) al terminar de
    // editarlo en Monaco. NO pasa por "guardar !" (que vuelca el mapa entero)
    // ni toca el JSON del repo — exportar a git sigue siendo manual ("exportar
    // !"). Cada guardado versiona el valor anterior; para deshacer, "· *
    // restaurar" o, desde consola, window.AtomHistory / RestoreAtomVersion.
    if (typeof window.SetAtom !== "function") return; // frontend suelto: no-op
    if (typeof name !== "string" || name.endsWith("֎")) return; // refs DOM no

    const value = diarsaba.get(name);
    // Mismo criterio que "guardar ! ƒ": una ƒ se persiste como su código fuente.
    const serial = name.endsWith("ƒ")
        ? String(value).replace(/\r\n/g, "\n").trim()
        : value;

    try {
        await host.kv.set(name, JSON.stringify(serial));
    } catch (e) {
        // El autosave no debe romper la edición: si falla, se avisa y ya.
        console.error(`autosave de "${name}" falló:`, e);
    }
}

referencias de ƒ:
(nombre) => {
    // ¿Quién me REFERENCIA? La versión general de "padres de ƒ": places que
    // me contienen, listas/acciones/threads que me nombran, funciones cuyo
    // código me menciona, textos/vistas/estilos/mapas donde aparezco. Igual
    // que los padres, se CALCULA cada vez — la verdad vive en los átomos y
    // un índice guardado mentiría.
    //
    // Criterio: igualdad exacta donde la referencia es estructural (elemento
    // de lista, hijo de place) y SUBCADENA donde es texto (código ƒ, §, <,
    // {, mapas :) — así también aparecen las refs compuestas, a cambio de
    // algún falso positivo si un nombre contiene a otro.
    const refs = [];
    for (const [k, v] of diarsaba.entries()) {
        if (typeof k !== "string" || k === nombre || k.endsWith("֎")) continue;
        let lo_referencia = false;
        if (k.endsWith("@") && v && typeof v === "object" && !Array.isArray(v)) {
            lo_referencia = Object.prototype.hasOwnProperty.call(v, nombre);
        } else if (Array.isArray(v)) {
            lo_referencia = v.includes(nombre);
        } else if (typeof v === "function") {
            lo_referencia = String(v).includes(nombre);
        } else if (typeof v === "string") {
            lo_referencia = v.includes(nombre);
        } else if (v && typeof v === "object") {
            try { lo_referencia = JSON.stringify(v).includes(nombre); } catch (_) {}
        }
        if (lo_referencia) refs.push(k);
    }
    return refs;
}

registrar ejecución ƒ:
(nombre, ok, valor) => {
    // Bitácora: apila el resultado (o el error) de cada acción en "salida #" y
    // hace parpadear su chip. La llama "threads" al correr un !. "salida #" es
    // efímera (va en skipKeys de guardar): un log no viaja al repo.
    const ignora = diarsaba.get("bitácora ignora #");
    // La fontanería de la UI (clic, menú) pasa por threads en cada gesto; sin
    // esta lista, la bitácora sería una pared de ruido.
    if (Array.isArray(ignora) && ignora.includes(nombre)) return;

    const t = new Date().toTimeString().slice(0, 8);
    let linea;
    if (ok) {
        let corto = "";
        if (valor !== undefined) {
            try { corto = typeof valor === "string" ? valor : JSON.stringify(valor); }
            catch (_) { corto = String(valor); }
            if (corto && corto.length > 60) corto = corto.slice(0, 57) + "…";
        }
        linea = `${t} ✓ ${nombre}` + (corto ? ` → ${corto}` : "");
    } else {
        const msg = (valor && valor.message) ? valor.message : String(valor);
        linea = `${t} ✗ ${nombre} · ${msg}`;
    }

    const log = diarsaba.get("salida #") || [];
    log.unshift(linea); // el más reciente primero
    if (log.length > 50) log.length = 50;
    diarsaba.set("salida #", log);

    // Monocromo: ok y error se distinguen por intensidad y duración, no por tono
    // (el detalle exacto vive en la bitácora). El error dura más.
    host.scene.flash(nombre, ok ? "bitacora-ok" : "bitacora-error", ok ? 700 : 1300);
}

resaltar chip ƒ:
