restaurar version ƒ:
async (name, version) => {
    // Aplica una versión histórica EN VIVO: la mete en el mapa (recompilando si
    // es ƒ), la persiste (lo que a su vez versiona el valor actual, así que
    // restaurar también se deshace) y repinta si hace falta. No hace falta
    // recargar, a diferencia del viejo "· * restaurar".
    let valor = version.value;
    if (name.endsWith("ƒ")) {
        try { valor = createFunction(String(valor)); }
        catch (e) { host.notify(`esa versión no compila: ${e && e.message ? e.message : e}`); return false; }
    }

    diarsaba.set(name, valor);
    await diarsaba.get("persistir atomo ƒ")(name);

    // Si es el place activo, repintarlo para ver la disposición restaurada.
    if (name === diarsaba.get("current place §") && name.endsWith("@")) {
        diarsaba.set("pointer up event", { target: { textContent: name, nodeName: "SPAN" } });
        diarsaba.get("on double tap place ƒ")();
    }
    return true;
}

show context menu ƒ:
() => {
    const event = diarsaba.get("pointer up event");

    // En panorámica no hay menús: se navega con clic (entrar/salir).
    if (diarsaba.get("panorámica activa §")) return;

    // Los modales (editor Monaco, modal de nombre, botón de mover) viven
    // ENCIMA del lienzo, pero este manejador escucha toda la ventana. Sin
    // esto, un doble clic dentro del editor se lee como doble clic en un
    // chip: el título del modal ES el nombre del átomo, sigilo incluido.
    if (event.target.closest && event.target.closest(".editor-overlay, .modal-content")) return;

    if (diarsaba.get("es fondo ƒ")(event.target)) {
        const currentMenu = diarsaba.get("current menu");
        if (currentMenu && typeof currentMenu.remove === "function") {
                        currentMenu.remove();
        }

        diarsaba.set(
            "current menu",
            diarsaba.get("create list menu ƒ")(diarsaba.get("atom name list #"))
        );

        // Coordenadas de MUNDO, no de pantalla: "add to place ƒ" y
        // "create chip ƒ" operan en el plano z=0. (y invertida: los places
        // guardan y hacia abajo.) Si no hay escena, caen a pantalla, que en
        // el body plano es lo mismo.
        const p = diarsaba.get("3d punto en plano ƒ")(event.clientX, event.clientY);
        diarsaba.set("open x $", p ? p.x : event.clientX);
        diarsaba.set("open y $", p ? -p.y : event.clientY);
    } else {
        const type = event.target.textContent.slice(-1);
        const name = event.target.textContent;

        diarsaba.get("show options list ƒ")(type, name);
    }
}

show options list ƒ:
(type, name) => {
    // 1. Limpiar el menú anterior si existe
    const currentMenu = diarsaba.get("current chip menu");
    if (currentMenu instanceof Element) {
        currentMenu.remove();
    }

    // 2. Obtener los recursos compartidos que usan todas las ramas
    const event = diarsaba.get("pointer up event");
    const createMenu = diarsaba.get("create list menu ƒ");
    const target = event.target;

    // Variables que determinarán cómo se creará el menú
    let menuOptions;
    let menuArgs = [];

    // 3. Determinar las opciones y argumentos según el caso
    if (/^\[\d+\]/.test(name)) {
        menuOptions = diarsaba.get("list option [] #");
        menuArgs = [target.parentElement.dataset.parent, name];
    } else if (diarsaba.get("types list #").includes(type)) {
        menuOptions = diarsaba.get(`list option ${type} #`);
        menuArgs = [name];
    } else {
        const fallbackType = "֎";
        const parentDataset = target.dataset.parent;
        const lastChar = parentDataset.slice(-1);

        menuOptions = diarsaba.get(`list option ${fallbackType} ${lastChar} #`);
        menuArgs = [parentDataset];
    }

    // 4. Crear y guardar el nuevo menú en un solo lugar
    const newMenu = createMenu(menuOptions, ...menuArgs);
    diarsaba.set("current chip menu", newMenu);
}

todo el estilo {:
/* Paleta monocroma: negro, blanco y blancos translúcidos. La jerarquía
   visual la da SOLO la opacidad — no hay matices de color en ningún lado.
   Si algo necesita destacar, sube de nivel (0.08 → 0.18), no cambia de tono. */
:root {
    --graph-bg: #000000;
    --graph-bg-elevated: rgba(255, 255, 255, 0.08);
    --graph-bg-strong: rgba(0, 0, 0, 0.92);
    --graph-border: rgba(255, 255, 255, 0.14);
    --graph-border-active: rgba(255, 255, 255, 0.24);
    --graph-text: #ffffff;
    --graph-text-muted: rgba(255, 255, 255, 0.62);
    --graph-shadow: 0 18px 48px rgba(0, 0, 0, 0.35);
    --graph-font: ui-monospace, "Cascadia Mono", Consolas, "Courier New", monospace;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* La monoespaciada se declara una sola vez aquí y todo lo demás la hereda:
   los chips SON el código, así que deben medir igual que el editor. */
body {
    background: var(--graph-bg);
    min-height: 100vh;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    font-family: var(--graph-font);
    color: var(--graph-text);
    padding: 20px;
}

.object-name {
    position: absolute;
    font-size: 1rem;
    color: var(--graph-text);
    font-weight: 500;
    cursor: pointer;
    /* En em: el chip entero escala con el font-size que escribe el
       render (la z es tamaño). Texto nítido: es layout de verdad, no
       una textura escalada. */
    padding: 0.375em 0.75em;
    border-radius: 999px;
    /* OJO: ni transform ni left/top/font-size en la transición — el
       render 3d los escribe en cada frame y una transición haría nadar
       los chips tras la cámara. */
    transition: background-color 0.15s ease, border-color 0.15s ease;
    width: fit-content;
    background: var(--graph-bg-elevated);
    border: 1px solid var(--graph-border);
    box-shadow: var(--graph-shadow);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    outline: none;
    user-select: none;
}

.object-name:hover {
    background: rgba(255, 255, 255, 0.12);
    border-color: var(--graph-border-active);
}

.object-name:focus {
    border: 1px solid rgba(255, 255, 255, 0.55);
}

.object-name:active {
    background: rgba(255, 255, 255, 0.18);
}

/* El lienzo 3d cubre la ventana y queda detrás de menús y modales, que
   son capas de PANTALLA (se anclan con getBoundingClientRect). Los
   chips se PROYECTAN a left/top + font-size (billboard): sin matrix3d
   el texto se rasteriza a su tamaño final y queda nítido. */
.escena-3d {
    position: fixed;
    inset: 0;
    z-index: 0;
    overflow: hidden;
}

.context-menu {
    position: absolute;
    background: var(--graph-bg-strong);
    border-radius: 14px;
    box-shadow: var(--graph-shadow);
    border: 1px solid var(--graph-border);
    z-index: 1000;
    min-width: 140px;
    max-height: min(360px, 60vh);
    overflow-y: auto;
    overflow-x: hidden;
    transition: opacity 0.1s ease, transform 0.1s ease;
    user-select: none;
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
}

/* Barra de scroll discreta en los menús.
   Se afina en vez de ocultarse: una lista larga sin ninguna señal de que hay
   más abajo se siente rota.

   Ojo con scrollbar-width: declararlo hace que Chromium —y WebView2 lo es—
   IGNORE por completo ::-webkit-scrollbar y vuelva a su barra nativa. Por eso
   aquí NO se declara: es lo que deja pasar el ancho de 6px de abajo. */
.context-menu::-webkit-scrollbar {
    width: 6px;
}

.context-menu::-webkit-scrollbar-track {
    background: transparent;
}

.context-menu::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.14);
    border-radius: 999px;
}

.context-menu::-webkit-scrollbar-thumb:hover {
    background: rgba(255, 255, 255, 0.28);
}

.menu-item {
    padding: 6px 12px;
    font-size: 0.75rem;
    color: var(--graph-text-muted);
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 6px;
    user-select: none;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.menu-item:last-child {
    border-bottom: none;
}

.menu-item:hover {
    background: rgba(255, 255, 255, 0.08);
}

.menu-item:active {
    background: rgba(255, 255, 255, 0.12);
}

.modal-content {
    position: absolute;
    left: 50%;
    top: 50%;
    padding: 1rem;
    border: 1px solid var(--graph-border);
    border-radius: 18px;
    background: rgba(0, 0, 0, 0.88);
