/* Panel del historial: como la bitácora, pero sus líneas SÍ se pulsan
   (abren el diff de esa versión). */
.historial-panel {
    position: absolute;
    background: var(--graph-bg-strong);
    border-radius: 14px;
    box-shadow: var(--graph-shadow);
    border: 1px solid var(--graph-border);
    z-index: 1600;
    min-width: 200px;
    max-width: 460px;
    max-height: min(360px, 60vh);
    overflow-y: auto;
    padding: 6px;
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
}

.historial-item {
    padding: 6px 10px;
    border-radius: 8px;
    cursor: pointer;
    font-size: 0.75rem;
    color: var(--graph-text-muted);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.historial-item:hover {
    background: rgba(255, 255, 255, 0.1);
    color: var(--graph-text);
}

/* Diff del historial: pista tenue en la cabecera y botón de restaurar
   (relleno, como guardar: es la acción primaria del diff). */
.diff-hint {
    color: var(--graph-text-muted);
    font-size: 11px;
    font-style: italic;
    font-weight: 400;
}

.restore-button {
    border: 1px solid var(--graph-border-active);
    border-radius: 6px;
    background: rgba(255, 255, 255, 0.14);
    color: var(--graph-text);
    padding: 6px 12px;
    font-size: 12px;
    cursor: pointer;
    transition: all 0.2s;
    display: flex;
    align-items: center;
    gap: 6px;
    font-family: inherit;
}

.restore-button:hover { background: rgba(255, 255, 255, 0.24); }

/* Panorámica: la etiqueta del place se marca con más borde para leerse
