async (dataset) => {
    // Materializa "<nombre> parents @" como place con los padres de AHORA.
    // Es una FOTO a demanda, no un índice vivo: volver a pulsar la rehace.
    // Que NO se mantenga sola es deliberado — la verdad son los places, y
    // "· * padres" la consulta en vivo; esto solo deja un acceso directo
    // navegable para cuando conviene tenerlo a mano.
    const nombre = dataset.parent;
    const padres = diarsaba.get("padres de ƒ")(nombre);
    const placeName = `${nombre} parents @`;

    // Los padres se disponen en la rejilla habitual de los places.
    const posiciones = {};
    padres.forEach((p, i) => {
        posiciones[p] = { x: 40 + (i % 3) * 300, y: 90 + Math.floor(i / 3) * 52 };
    });
    diarsaba.set(placeName, posiciones);
    await diarsaba.get("persistir atomo ƒ")(placeName);

    // Su chip aparece bajo el átomo, listo para entrar con doble clic. No se
    // registra en el place actual a propósito: colocarlo es decisión tuya
    // ("· * tomar" si lo quieres fijo).
    if (!(diarsaba.get(`${placeName} ֎`) instanceof Element)) {
        const chip_ancla = diarsaba.get(`${nombre} ֎`);
        const rect = (chip_ancla instanceof Element)
            ? chip_ancla.getBoundingClientRect()
            : { left: diarsaba.get("pointer x") || 0, top: diarsaba.get("pointer y") || 0, width: 0, height: 0 };
        const sx = rect.left;
        const sy = rect.top + (rect.height || 0) + 14;
        const mundo = diarsaba.get("3d punto en plano ƒ")(sx, sy);
        const chip = diarsaba.get("create chip ƒ")(
            mundo ? mundo.x : sx,
            mundo ? -mundo.y : sy,
            placeName,
            "",
            "@"
        );
        diarsaba.set(`${placeName} ֎`, chip);
    }
}

