· ֎* padre ƒ:
(dataset) => {
    const rect = diarsaba.get(`${dataset.parent} ֎ ֎`).getBoundingClientRect();

    // A la izquierda del hijo. Pantalla → mundo: create chip ƒ espera
    // coordenadas del plano, y style.left ya no manda (lo escribe el
    // proyector); el ajuste fino se hace sobre la posición del objeto.
    const sx = rect.left - 10;
    const sy = rect.top + rect.height / 2;
    const mundo = diarsaba.get("3d punto en plano ƒ")(sx, sy);
    const chip = diarsaba.get("create chip ƒ")(
        mundo ? mundo.x : sx,
        mundo ? -mundo.y : sy,
        dataset.parent,
        "",
        dataset.parent.slice(0, 1)
    );

    // El chip se centra en su punto: correrlo medio ancho lo deja pegado a
    // la izquierda del ancla (aprox a escala 1).
    if (chip._obj3d) {
        chip._obj3d.position.x -= chip.offsetWidth / 2;
        diarsaba.get("3d render ƒ")();
    } else {
        chip.style.left = `${sx - chip.offsetWidth - 10}px`;
    }
    diarsaba.set(`${dataset.parent} ֎`, chip);
}
